from collections import deque
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                                seen[ny][nx]=True; q.append((ny,nx))
                ys=[y for y,_ in cells]; xs=[x for _,x in cells]
                out.append((col,min(xs)-min(xs),min(ys),cells,(max(ys)+1-min(ys),max(xs)+1-min(xs))))
    return out
