    shapes=[o for o in objs if len(o[1])>1]
    noises=[o for o in objs if len(o[1])==1]
    res=[[None]*W for _ in range(H)]
    blocked=lambda cells:(any(y>=H or x>=W for y,x in cells) or any(res[y][x] is not None for y,x in cells))
